-- L1 run index (docs/l1-literal-schema.md, "Scale"): the runs view per
-- committed transcript records generation, one row per run and a receipt per
-- build written after its runs. Written only by the reconciliation worker.
-- Each build is an immutable snapshot (build_revision is in the key); the
-- newest receipt names the build readers read. The free-text columns get a
-- column TTL by hand (chkit cannot express it): text never outlives the
-- transcript's 365 days, while runs stay three years.

CREATE TABLE IF NOT EXISTS rudel.run_index
(
  `organization_id` String COMMENT 'Owning workspace ID; tenant boundary.',
  `user_id` String COMMENT 'Session owner.',
  `session_id` String COMMENT 'Native session ID within organization and user.',
  `revision` UInt64 COMMENT 'Raw transcript revision of the transcript records generation.',
  `parser_version` UInt16 COMMENT 'Transcript records parser version of the generation.',
  `index_version` UInt16 COMMENT 'Version of the run index rules; a new version is a new generation.',
  `agent_id` String COMMENT 'Transcript stream; empty for the main stream and the receipt.',
  `start_record` UInt32 COMMENT 'Raw record index of the record that starts the run (its prompt), as in the L1 edge run ids; 4294967295 for the receipt.',
  `row_kind` LowCardinality(String) COMMENT 'run, or receipt: one per build, written after its runs, holding session facts and committing the build.',
  `source` LowCardinality(String) COMMENT 'Transcript source: claude_code or codex.',
  `turn_idx` UInt32 COMMENT 'Run number within the stream; zero for the receipt.',
  `run_id` String COMMENT 'L1 run node id (user/source/session/agent/start record, percent-encoded), equal to l1_edges.from_id of the run.',
  `build_revision` UInt64 COMMENT 'Worker build revision that wrote the snapshot. In the key: each build is an immutable snapshot, and the newest receipt names the build readers read.',
  `built_at` DateTime64(3, 'UTC') COMMENT 'UTC millisecond time the worker wrote the row.',
  `session_date` DateTime64(3, 'UTC') COMMENT 'Session date of the generation; retention is measured from it.',
  `unrecorded_facts` Array(LowCardinality(String)) COMMENT 'Fact columns of this row whose values are unknown, not none: the parser version or agent cannot record them, or the usage extraction was incomplete.',
  `agent_version` LowCardinality(Nullable(String)) COMMENT 'First agent version recorded in the run (Claude Code version, Codex cli_version); NULL when the parser version or agent does not record it.',
  `entrypoint` LowCardinality(Nullable(String)) COMMENT 'First entrypoint recorded in the run (Claude Code entrypoint, Codex originator); NULL when the parser version or agent does not record it.',
  `started_at` DateTime64(3, 'UTC') COMMENT 'Timestamp of the run\'s first record.',
  `ended_at` DateTime64(3, 'UTC') COMMENT 'Timestamp of the run\'s last non-meta record; started_at when it has none.',
  `end_record` UInt32 COMMENT 'Start record of the next run in the stream, or one past the run\'s last record: usage on lines in [start_record, end_record) belongs to the run.',
  `minutes` Float64 COMMENT 'Wall-clock minutes from the first record to the last non-meta record.',
  `active_minutes` Float64 COMMENT 'Sum of the gaps between non-meta records, each capped at five minutes.',
  `record_count` UInt32 COMMENT 'Transcript lines of the run.',
  `raw_chars` UInt64 COMMENT 'Characters of the run\'s records before any cap.',
  `duration_ms` Nullable(UInt32) COMMENT 'Sum of the duration_ms of the run\'s Codex task_complete and turn_aborted events; NULL when the parser version or agent does not record it or no event records it.',
  `time_to_first_token_ms` Nullable(UInt32) COMMENT 'time_to_first_token_ms of the run\'s first Codex task_complete; NULL when the parser version or agent does not record it or no event records it.',
  `prompt_head` Nullable(String) COMMENT 'First 160 characters of the run\'s first genuine prompt; NULL once the text retention passed.' TTL toDate(session_date) + toIntervalDay(365),
  `genuine_prompts` UInt32 COMMENT 'Human prompts in the run (queued prompts included, delegated tasks not).',
  `turn_origin` LowCardinality(Nullable(String)) COMMENT 'Claude turnOrigin of the run\'s starting prompt; NULL when the parser version or agent does not record it.',
  `prompt_source` LowCardinality(Nullable(String)) COMMENT 'Claude promptSource of the run\'s starting prompt; NULL when the parser version or agent does not record it.',
  `origin_kind` LowCardinality(Nullable(String)) COMMENT 'Claude origin.kind of the run\'s starting prompt; NULL when the parser version or agent does not record it.',
  `trigger_turn` LowCardinality(Nullable(String)) COMMENT 'First Codex inter-agent trigger_turn recorded in the run (true or false); NULL when the parser version or agent does not record it.',
  `thread_source` LowCardinality(Nullable(String)) COMMENT 'Codex session_meta thread_source of the run\'s stream (user, subagent, guardian_review); NULL when the parser version or agent does not record it.',
  `prompt_origin_basis` LowCardinality(String) COMMENT 'native when the starting prompt or its stream records a native origin field, else wrapper: the prompt kind comes only from the parser\'s wrapper rules.',
  `permission_mode` LowCardinality(Nullable(String)) COMMENT 'First Claude permissionMode recorded in the run; NULL when the parser version or agent does not record it.',
  `permission_modes` Array(LowCardinality(String)) COMMENT 'Every Claude permissionMode recorded in the run, sorted.',
  `auto_mode_bash_first` LowCardinality(Nullable(String)) COMMENT 'First Claude auto_mode bashFirst in the run (true or false); NULL when the parser version or agent does not record it.',
  `auto_mode_bash_first_steer` LowCardinality(Nullable(String)) COMMENT 'First Claude auto_mode bashFirstSteer in the run; NULL when the parser version or agent does not record it.',
  `auto_mode_bypass` LowCardinality(Nullable(String)) COMMENT 'First Claude auto_mode bypass in the run (true or false); NULL when the parser version or agent does not record it.',
  `auto_mode_steer_only` LowCardinality(Nullable(String)) COMMENT 'First Claude auto_mode steerOnly in the run (true or false); NULL when the parser version or agent does not record it.',
  `auto_mode_consent_flow` LowCardinality(Nullable(String)) COMMENT 'First Claude auto_mode autoModeConsentFlow in the run (true or false); NULL when the parser version or agent does not record it.',
  `approval_policy` LowCardinality(Nullable(String)) COMMENT 'First Codex turn_context approval_policy of the run; NULL when the parser version or agent does not record it.',
  `approvals_reviewer` LowCardinality(Nullable(String)) COMMENT 'First Codex turn_context approvals_reviewer of the run; NULL when the parser version or agent does not record it.',
  `sandbox_policy` LowCardinality(Nullable(String)) COMMENT 'First Codex turn_context sandbox_policy type of the run; NULL when the parser version or agent does not record it.',
  `sandbox_network_access` LowCardinality(Nullable(String)) COMMENT 'First Codex turn_context sandbox network_access of the run (true or false); NULL when the parser version or agent does not record it.',
  `permission_profile` LowCardinality(Nullable(String)) COMMENT 'First Codex turn_context permission_profile type of the run; NULL when the parser version or agent does not record it.',
  `collaboration_mode` LowCardinality(Nullable(String)) COMMENT 'First Codex collaboration mode of the run (turn_context or task_started); NULL when the parser version or agent does not record it.',
  `model` LowCardinality(Nullable(String)) COMMENT 'First model recorded in the run (Claude assistant message.model, Codex turn_context model); NULL when the parser version or agent does not record it.',
  `models` Array(LowCardinality(String)) COMMENT 'Every model recorded in the run\'s records, sorted.',
  `effort` LowCardinality(Nullable(String)) COMMENT 'First effort recorded in the run (Claude assistant effort, Codex turn_context effort); NULL when the parser version or agent does not record it.',
  `per_turn_effort` LowCardinality(Nullable(String)) COMMENT 'First Claude perTurnEffort recorded in the run; NULL when the parser version or agent does not record it.',
  `context_window` Nullable(UInt32) COMMENT 'First Codex task_started model_context_window of the run; NULL when the parser version or agent does not record it or none was.',
  `context_input_tokens_at_start` Nullable(UInt64) COMMENT 'Context input tokens of the run\'s first verified usage event; NULL without one.',
  `tool_calls` UInt32 COMMENT 'Tool call records of the run.',
  `failed_calls` UInt32 COMMENT 'Calls whose result is an error or has a non-zero exit code, counted once per call.',
  `edits` UInt32 COMMENT 'Distinct files written, edited or deleted by native edits, patches or unconditional shell commands whose call did not fail.',
  `reads` UInt32 COMMENT 'Tool calls in the read group.',
  `searches` UInt32 COMMENT 'Tool calls in the search group.',
  `not_found` UInt32 COMMENT 'Failed read or search results whose text says not found, no such file, ENOENT or No files found.',
  `denied_calls` Nullable(UInt32) COMMENT 'Calls whose result records a denial_kind; NULL when the parser version or agent does not record it.',
  `interrupted_calls` Nullable(UInt32) COMMENT 'Calls whose result records interrupted = true; NULL when the parser version or agent does not record it.',
  `timed_out_calls` Nullable(UInt32) COMMENT 'Calls whose result records timedOutAfterMs; NULL when the parser version or agent does not record it.',
  `mcp_calls` Nullable(UInt32) COMMENT 'Calls with a recorded MCP server; NULL when the parser version or agent does not record it.',
  `mcp_servers` Array(LowCardinality(String)) COMMENT 'MCP servers recorded on the run\'s calls, sorted.',
  `skills` Array(String) COMMENT 'Skills of the run: Claude attributionSkill values and the skill input of Skill tool calls, sorted.',
  `slash_commands` Array(String) COMMENT 'Command names of the run\'s Claude slash-command records, without the leading slash, sorted.',
  `subagent_types` Array(LowCardinality(String)) COMMENT 'subagent_type inputs of the run\'s Claude Task and Agent tool calls, sorted.',
  `compactions` UInt32 COMMENT 'Compaction records of the run.',
  `compact_trigger` LowCardinality(Nullable(String)) COMMENT 'First Claude compactMetadata trigger of the run; NULL when the parser version or agent does not record it.',
  `compact_pre_tokens` Nullable(UInt64) COMMENT 'First Claude compactMetadata preTokens of the run; NULL when the parser version or agent does not record it or none was.',
  `aborted` LowCardinality(Nullable(String)) COMMENT 'true when a record of the run says aborted (Codex turn_aborted, Claude interruptedByShutdown), false when records say only false, empty when none says; NULL when the parser version or agent does not record it.',
  `abort_reason` LowCardinality(Nullable(String)) COMMENT 'First Codex turn_aborted reason of the run; NULL when the parser version or agent does not record it.',
  `turn_error` Nullable(String) COMMENT 'First Codex task_complete error message of the run; NULL when the parser version or agent does not record it or once the text retention passed.' TTL toDate(session_date) + toIntervalDay(365),
  `turn_error_kind` LowCardinality(Nullable(String)) COMMENT 'First Codex task_complete codex_error_info of the run; NULL when the parser version or agent does not record it.',
  `interrupt_markers` UInt32 COMMENT 'Interrupt marker records of the run (Claude [Request interrupted by user], Codex turn_aborted wrappers).',
  `stop_reason` LowCardinality(Nullable(String)) COMMENT 'Last Claude assistant stop_reason recorded in the run; NULL when the parser version or agent does not record it.',
  `hook_stop_reason` Nullable(String) COMMENT 'First Claude stop hook stopReason of the run; NULL when the parser version or agent does not record it or once the text retention passed.' TTL toDate(session_date) + toIntervalDay(365),
  `prevented_continuation` LowCardinality(Nullable(String)) COMMENT 'true when a stop hook summary of the run records preventedContinuation, false when they record only false; NULL when the parser version or agent does not record it.',
  `hook_count` Nullable(UInt32) COMMENT 'Sum of the hookCount of the run\'s stop hook summaries; NULL when the parser version or agent does not record it or none was.',
  `hook_errors` Nullable(String) COMMENT 'JSON array of the run\'s stop hook hookErrors in record order; NULL when the parser version or agent does not record it or once the text retention passed.' TTL toDate(session_date) + toIntervalDay(365),
  `hook_runs` Nullable(String) COMMENT 'JSON array of the run\'s stop hook hookInfos (command, durationMs) in record order; NULL when the parser version or agent does not record it or once the text retention passed.' TTL toDate(session_date) + toIntervalDay(365),
  `api_errors` Nullable(UInt32) COMMENT 'Claude API error records of the run; NULL when the parser version or agent does not record it.',
  `api_error` Nullable(String) COMMENT 'First Claude API error of the run; NULL when the parser version or agent does not record it or once the text retention passed.' TTL toDate(session_date) + toIntervalDay(365),
  `api_error_statuses` Array(LowCardinality(String)) COMMENT 'Claude apiErrorStatus values of the run, sorted.',
  `retry_attempts` Nullable(UInt32) COMMENT 'Claude API retry records of the run; NULL when the parser version or agent does not record it.',
  `refusals` Nullable(UInt32) COMMENT 'Claude model refusal records of the run; NULL when the parser version or agent does not record it.',
  `fallback_model` LowCardinality(Nullable(String)) COMMENT 'First Claude fallbackModel of the run; NULL when the parser version or agent does not record it.',
  `goal` Nullable(String) COMMENT 'Last Codex thread goal objective set in the run; NULL when the parser version or agent does not record it or once the text retention passed.' TTL toDate(session_date) + toIntervalDay(365),
  `git_operations` Array(LowCardinality(String)) COMMENT 'Claude gitOperation keys of the run (push, pr, branch, commit), sorted.',
  `pushed_branches` Array(String) COMMENT 'Claude gitOperation push branches of the run, sorted.',
  `commit_shas` Array(String) COMMENT 'Claude gitOperation commit SHAs of the run as recorded, sorted.',
  `pr_urls` Array(String) COMMENT 'Pull request URLs of the run from Claude gitOperation and pr-link records, sorted.',
  `usage_observations` UInt32 COMMENT 'Usage events of the session\'s usage extraction verified on the run\'s lines; on the receipt, its events assigned to no run.',
  `usage_unpriced` UInt32 COMMENT 'Of usage_observations, events without a price.',
  `usage_model` LowCardinality(String) COMMENT 'Model of the run\'s latest usage event; empty without usage.',
  `cost_usd` Nullable(Float64) COMMENT 'Priced cost of usage_observations at pricing_version; NULL when none is priced.',
  `model_costs` Array(Tuple(String, Nullable(Float64), UInt32)) COMMENT 'Per model: priced cost (NULL when unpriced) and unpriced events, most expensive first.',
  `uncached_input_tokens` Nullable(UInt64) COMMENT 'Uncached input tokens of usage_observations; NULL without usage.',
  `cache_read_input_tokens` Nullable(UInt64) COMMENT 'Cache read input tokens of usage_observations; NULL without usage.',
  `cache_write_5m_input_tokens` Nullable(UInt64) COMMENT 'Five-minute cache write input tokens of usage_observations; NULL without usage.',
  `cache_write_1h_input_tokens` Nullable(UInt64) COMMENT 'One-hour cache write input tokens of usage_observations; NULL without usage.',
  `output_tokens` Nullable(UInt64) COMMENT 'Output tokens of usage_observations; NULL without usage.',
  `reasoning_output_tokens` Nullable(UInt64) COMMENT 'Reasoning output tokens of usage_observations; NULL without usage.',
  `pricing_version` LowCardinality(String) COMMENT 'Rate card version and pricing rules hash the costs were computed with.',
  `facts_truncated` Nullable(Bool) COMMENT 'Whether a record of the run dropped long fact values to the session fact budget; NULL when the parser version or agent does not record it.',
  `run_count` UInt32 COMMENT 'Receipt: runs of the generation. Its call, error, skill and model columns total or merge those of the runs.',
  `usage_receipt` String COMMENT 'Receipt: the usage extraction the costs were built from (generation:checksum, with :incomplete when it was not complete and usage is unknown); empty without usage.',
  `cost_state` Map(LowCardinality(String), String) COMMENT 'Receipt: the main stream\'s last Claude cost-state record (cost_usd, lines, durations), keyed by fact name; empty when none.',
  `title` Nullable(String) COMMENT 'Receipt: last Claude ai-title of the main stream; NULL when the parser version or agent does not record it or once the text retention passed.' TTL toDate(session_date) + toIntervalDay(365),
  `repository` String COMMENT 'Receipt: the session repository key as recorded (git remote, else package name, else project path).',
  `session_model` LowCardinality(String) COMMENT 'Receipt: the session model recorded at upload.'
) ENGINE = ReplacingMergeTree(build_revision)
PRIMARY KEY (`organization_id`, `user_id`, `session_id`, `revision`, `parser_version`, `index_version`, `build_revision`, `agent_id`, `start_record`)
ORDER BY (`organization_id`, `user_id`, `session_id`, `revision`, `parser_version`, `index_version`, `build_revision`, `agent_id`, `start_record`)
TTL toDate(session_date) + toIntervalDay(1095)
SETTINGS index_granularity = 1024, index_granularity_bytes = 1048576, non_replicated_deduplication_window = 1000, storage_policy = 's3'
COMMENT 'L1 runs per committed transcript generation, with a receipt per session generation written last; written only by the reconciliation worker.';
